-- Migration 1: volumes
-- Run once by the migration runner, inside one transaction, followed by
-- PRAGMA user_version = 1. No IF NOT EXISTS: if this ever runs against a
-- database that already has these objects, that is a bug and should fail loudly.

PRAGMA application_id = 0x46494C45;  -- 'FILE': marks the file as ours

CREATE TABLE volumes (
    -- Local row id, used for joins inside this file only. Never written
    -- anywhere else: SQLite may reuse it after the highest row is deleted.
    id INTEGER PRIMARY KEY,

    -- Stable identity, generated by the app (UUID v4, 16 bytes). This is the
    -- value the index shards store, so a recreated or restored catalog can
    -- never be matched to the wrong shard.
    uid BLOB NOT NULL UNIQUE CHECK (length(uid) = 16),

    -- Normalized by the app before insert (separators, trailing slash, and
    -- case for smb). The schema only guarantees it is present and unique.
    root TEXT NOT NULL UNIQUE CHECK (root <> ''),

    vtype TEXT NOT NULL CHECK (vtype IN ('smb', 'nfs', 'local')),

    -- Display label. Duplicates allowed.
    name TEXT NOT NULL CHECK (name <> ''),

    -- What the volume is doing right now.
    status TEXT NOT NULL DEFAULT 'offline'
        CHECK (status IN ('offline', 'online', 'scanning')),

    -- Why the last check or scan went wrong. NULL means no problem.
    -- Independent of status: a volume can be online with permission errors.
    last_error TEXT
        CHECK (last_error IN ('path_not_found', 'drive_not_found', 'permission_denied')),

    -- All timestamps are UTC, ISO 8601 with a Z suffix, so they sort as text
    -- and nobody has to guess the timezone.
    created_at TEXT NOT NULL
        DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),

    -- Maintained by trigger volumes_status_changed_at. Do not set by hand.
    status_changed_at TEXT NOT NULL
        DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),

    -- Set by the indexer when a scan completes. NULL means never scanned.
    -- An event, not a column change, so the app owns it, not a trigger.
    last_scanned_at TEXT
) STRICT;

-- Records when status actually changes. Setting status to its current
-- value is not a change and leaves the timestamp alone.
CREATE TRIGGER volumes_status_changed_at
    AFTER UPDATE OF status ON volumes
    WHEN NEW.status IS NOT OLD.status
BEGIN
    UPDATE volumes
    SET status_changed_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
    WHERE id = NEW.id;
END;

-- A volume's identity and location never change. Pointing a volume at a
-- different place would leave every indexed file in the shards describing
-- the wrong location. To move a volume, add a new one and retire the old.
CREATE TRIGGER volumes_identity_immutable
    BEFORE UPDATE OF uid, root, vtype ON volumes
    WHEN NEW.uid IS NOT OLD.uid
      OR NEW.root IS NOT OLD.root
      OR NEW.vtype IS NOT OLD.vtype
BEGIN
    SELECT RAISE(ABORT, 'volume uid, root and vtype are immutable; add a new volume instead');
END;